pub(super) fn contains(lat: f64, lon: f64) -> bool {
    let mut inside = false;
    for (&(start_lon, start_lat), &(end_lon, end_lat)) in RING.iter().zip(RING.iter().skip(1)) {
        let rise = end_lat - start_lat;
        let run = end_lon - start_lon;
        let cross = (lon - start_lon) * rise - (lat - start_lat) * run;
        if cross.abs() <= f64::EPSILON
            && (start_lat.min(end_lat)..=start_lat.max(end_lat)).contains(&lat)
            && (start_lon.min(end_lon)..=start_lon.max(end_lon)).contains(&lon)
        {
            return true;
        }
        if (start_lat > lat) != (end_lat > lat) && lon < start_lon + (lat - start_lat) * run / rise
        {
            inside = !inside;
        }
    }
    inside
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn covers_munich_and_garching() {
        assert!(contains(48.14966, 11.56794));
        assert!(contains(48.26244, 11.66799));
    }

    #[test]
    fn includes_boundary_vertices() {
        assert!(RING.iter().all(|&(lon, lat)| contains(lat, lon)));
    }

    #[test]
    fn excludes_heilbronn_and_straubing() {
        assert!(!contains(49.13749255253383, 9.216739822397306));
        assert!(!contains(48.88520921545141, 12.572104411469688));
    }
}

